class CounterError(ValueError):
    pass
class Counter:
    def __init__(self, value=0):
        self.value = value
    def add(self, delta):
        if delta < 0:
            raise CounterError('neg')
        self.value += delta
        return [self.value]
    def __len__(self):
        return self.value
    def __bool__(self):
        return self.value != 0

