import unittest
from helper import START
from counter import Counter, CounterError
class T(unittest.TestCase):
    def test_list(self):
        self.assertEqual(Counter().add(1), [1])
    def test_raises(self):
        with self.assertRaises(CounterError):
            Counter().add(-1)
    def test_len_and_type(self):
        item = Counter(3)
        self.assertEqual(len(item), 3)
        self.assertIsInstance(item, Counter)
    def test_bool(self):
        self.assertFalse(Counter(0))
        self.assertTrue(Counter(1))
    def test_set(self):
        item = Counter(1)
        item.value = 4
        self.assertEqual(item.value, 4)
    def test_helper(self):
        self.assertEqual(START, 0)
